import { createLogHost } from '@migaia/log-host'
import { reasoningPlugin } from '@migaia/log-plugin-reasoning'

/** 应用借用该数组观察每次流式写入的原始文本。 */
const fragments: string[] = []
/** 每次安装独立持有阶段与缓冲区。 */
const log = createLogHost({
  plugins: [
    reasoningPlugin({
      write: (text) => {
        fragments.push(text)
      }
    })
  ]
})
log.startThinking('Thinking')
log.thinking('inspect ')
log.thinking('the request')
log.endThinking()
log.startResponse()
log.response('Done.')
log.endResponse()
await log.shutdown('manual')

import { createLogHost } from '@migaia/log-host'
import { reasoningPlugin } from '@migaia/log-plugin-reasoning'

/** 应用接收每次原样流式写入，保留片段边界。 */
const fragments: string[] = []
/** 明确开启 host 跟踪的异步流式调度。 */
const log = createLogHost({
  plugins: [
    reasoningPlugin({
      labels: { thinking: 'Plan', response: 'Answer' },
      asyncOutput: true,
      write: (text) => {
        fragments.push(text)
      }
    })
  ]
})
log.thinking('inspect')
log.response('ready')
log.endResponse()
await log.flush()
await log.shutdown('manual')

